"""One-time, reviewable migration from the 5 September Ukrainian structure.

Sources are backed up before mutation. Refuses a second application. Diagrams,
inventory, numbering/provenance and gates are handled by companion scripts.
"""
from pathlib import Path
import re, json
ROOT=Path(__file__).resolve().parents[1]
SRC=ROOT/'docs/dissertation/condensed_translated_humanized_ukrainian'

def section(text, heading, level=3):
    start=text.index(heading)
    match=re.search(r'(?m)^#{1,'+str(level)+r'} ',text[start+len(heading):])
    end=start+len(heading)+match.start() if match else len(text)
    return text[start:end].strip()

def body(text): return text.split('\n',1)[1].strip()
def h(number,title,text): return f'### {number} {title}\n\n{text.strip()}\n\n'
def tbl(key,title,headers,rows):
    return f'<!-- evidence:{key} -->\n\n**Таблиця 4.X{key} – {title}.** Позначка «очікується» означає відсутність перевіреного вимірювання; наведені умови визначають протокол, а не результат.\n\n| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)+'\n\n'

def main():
    p3=SRC/'04_CHAPTER_3.md';p4=SRC/'05_CHAPTER_4.md'
    c3=p3.read_text(encoding='utf-8'); c4=p4.read_text(encoding='utf-8')
    assert '### 4.9.3 Поточна перевірка' in c4,'Migration already applied or source differs'
    backup=ROOT/'tmp/hierarchy_narrative_20260906/before';backup.mkdir(parents=True,exist_ok=True)
    for p in SRC.glob('0*.md'): (backup/p.name).write_bytes(p.read_bytes())
    parts={i:body(section(c3,f'### 3.6.{i} ')) for i in range(1,10)}
    motivations={
    'FRT':'''Зростання якості зі збільшенням пам’яті саме по собі не пояснює користі ієрархії: додаткові токени може використати й плоске подання. Тому місткість і спосіб її використання потрібно розглядати разом. Бюджетний фронтир зіставляє політики на тих самих точках вартості, а не порівнює довільну довгу ієрархічну історію з довільним коротким вікном. Він перевіряє, чи залишається компроміс між досяжністю та точністю відтворення залежним від масштабу ресурсу.

Наприклад, 1 792 токени дозволяють зберегти 28 детальних часових позицій по 64 токени або 56 грубих позицій по 16 токенів і 896 детальних комірок. Другий пакет охоплює давнішу історію, але не відтворює її з однаковою просторовою точністю. Вкладені грубі та детальні представлення не слід рахувати як різні фізичні моменти. Перевага ієрархії узгоджуватиметься з корисністю такого обміну; перевага плоского пакета — з більшою цінністю деталей у відповідній задачі. Зміна знака між бюджетами чи ініціалізаціями потребує опису локальних умов, а не побудови універсальної точки переходу.''',
    'ALC':'''Бюджетний фронтир залишає відкритим питання, чи обраний поділ ресурсу між рівнями є вдалим. Однакова кількість токенів може відповідати дуже різній часовій підтримці та кількості докладно представлених моментів. Рівнобюджетний дослід розподілу тому відокремлює місткість пакета від його структури: за сталої вартості перевіряється, чи слід витрачати ресурс на грубу основу, недавні деталі або деталі різного віку.

Збалансований і геометричний пакети мають однакові 56 грубих позицій і 896 детальних комірок, проте розміщують деталі по-різному. Їхнє зіставлення інформативніше щодо вікового розкладу, ніж порівняння збалансованої політики з орієнтованою на досяжність, де змінюється також частка рівнів. Висновок формулюється для конкретної пари політик. Відсутність переваги складнішої структури є допустимим результатом: вона означає, що доступна модель не використала запропонований розподіл краще за простіший. Вибір опорної неплоскої політики для дослідів рівнів не перетворює її на переможця над плоскою.''',
    'CEX':'''Рівнобюджетне порівняння змішує дві протилежні зміни: додавання давньої історії та вилучення деталей. Щоб з’ясувати, чи несе груба давня підтримка корисне свідчення взагалі, недавню детальну частину залишають незмінною. Далі додають лише грубі позиції за її межами. Така конструкція відповідає практичному питанню граничної користі додаткової пам’яті, а не питанню найкращого пакета за однакової вартості.

Перехід від нуля до чотирьох грубих позицій зберігає шість докладних кадрів і додає 64 токени; досяжність зростає з 6 до 10 моментів. Якщо помилка зменшується, це свідчить про корисність доступної додаткової інформації для цього предиктора. Якщо крива насичується, збільшення пам’яті може перестати бути виправданим. Якщо помилка зростає, можливі завади від грубих ознак або труднощі використання довшої послідовності. Жоден напрям не відокремлює автоматично інформаційний ефект від зміни обчислень, тому разом із якістю подається ресурсна ціна.''',
    'STS':'''Навіть за сталої часової підтримки грубого рівня деталі можна витрачати на небагато повних кадрів або на більше частково представлених моментів. Цей вибір важливий, коли точний вигляд об’єкта потрібний лише в окремих місцях, а його рух — у багатьох моментах. Дослід фіксує грубу основу та глобальну квоту деталей і змінює просторову повноту одного вибраного моменту разом із кількістю таких моментів.

Глобальні 256 детальних токенів можна розмістити як чотири позиції по 64 комірки або як 32 позиції по вісім комірок. Ці пакети мають однакову кількість деталей, але різну просторово-часову геометрію. Недавній, рівномірний і геометричний розклади перевіряють, чи важливе також розташування цих позицій за віком. Дослід не є перевіркою навчуваного маршрутизатора: членство задається планом. Стійка перевага певного розкладу характеризує використання заданої геометрії, тоді як змішані напрями вказують на залежність від конкретної щільності та віку деталей.''',
    'LVL':'''Два рівні задають лише один компроміс між точністю та охопленням. Додавання ще грубішого рівня дозволяє підтримати давню історію дешевшими ознаками, але витрачає частину бюджету, раніше доступного іншим рівням. Тому кількість рівнів не можна трактувати як безкоштовне збільшення виразності: за сталого бюджету вона змінює розподіл інформації.

Верхня сітка 2×2 для 96 моментів займає 384 токени, залишаючи 1 408 для грубого й детального рівнів. Конкретний залишковий розподіл визначається правилом залежності від опорної дворівневої політики, а не підбирається за результатом трирівневої моделі. Якщо третій рівень допомагає, висновок стосується цього перерозподілу й предиктора. Якщо він не допомагає, додатковий масштаб міг втратити більше корисних деталей, ніж додати часової інформації. Один та два рівні повторно використовують контрольні точки, щоб зіставлення не вимагало зайвих навчань і не рахувало той самий доказ двічі.''',
    'OVR':'''Ієрархія визначає не лише масштаби, а й те, чи описують різні рівні один фізичний момент. Вкладене подання може давати взаємодоповнювальні ознаки або дублювати інформацію. Взаємовиключне звільняє місце для інших моментів. Залишкове намагається явно відокремити деталь від її грубої основи. Ці механізми потрібно описувати через фактичний вміст токена, а не лише через назву політики.

Для одного моменту вкладена схема зберігає грубу ознаку та звичайну деталь; залишкова — грубу ознаку та різницю проєкцій; взаємовиключна — деталь замість відповідної грубої підтримки. Звільнена місткість останньої схеми використовується за визначеним планом. Отже, порівняння перевіряє пакет представлення цілком: одночасно можуть змінюватися часовий доступ і ознаки. Перевагу залишкової схеми не слід називати доказом меншої надлишковості без додаткової діагностики; достатній висновок — її емпірична доцільність за фіксованого бюджету. Несприятливий результат також зберігається, бо визначає межу відповідного кодування.'''}
